  values ('3f775461-7914-834b-88f2-c38d256c8b63'::uuid, uid, 'BCG (Boston Consulting Group)', 'Consultant, Singapore (Post-MBA)', (select id from sectors where user_id = uid and path = array['Management Consulting', 'Singapore']::text[]), 'saved'::app_stage, null::closed_reason, '{"company":"BCG (Boston Consulting Group)","role":"Consultant, Singapore (Post-MBA)","roleFamily":"consulting","sectorPath":["Management Consulting","Singapore"],"skills":["strategy-consulting"],"keywords":["strategy","consulting","mba"],"seniority":null,"visaNote":"Eligibility: This role is open to INSEAD 26D students, IE MBAs graduating between Dec 2026 - Mar 2027, and second year MBA students from ESADE, IESE, HEC, and LBS, who are seeking full-time roles.","location":"Singapore"}'::jsonb, 'Eligibility: This role is open to INSEAD 26D students, IE MBAs graduating between Dec 2026 - Mar 2027, and second year MBA students from ESADE, IESE, HEC, and LBS, who are seeking full-time roles.

Boston Consulting Group partners with leaders in business and society to tackle their most important challenges and capture their greatest opportunities. BCG was the pioneer in business strategy when it was founded in 1963. Today, we help clients with total transformation-inspiring complex change, enabling organizations to grow, building competitive advantage, and driving bottom-line impact.

To succeed, organizations must blend digital and human capabilities. Our diverse, global teams bring deep industry and functional expertise and a range of perspectives to spark change. BCG delivers solutions through leading-edge management consulting along with technology and design, corporate and digital ventures-and business purpose. We work in a uniquely collaborative model across the firm and throughout all levels of the client organization, generating results that allow our clients to thrive.', '4cbf015f-5c28-8a1d-8ccf-f4336e9c5075'::uuid, null::uuid, 'Imported from CVbuilder - confirm whether this was submitted, then advance the stage', '2026-08-26'::date, null::date, '2026-08-26T15:20:53.315Z'::timestamptz)
